bool CUnit::PlayUnitSound( const char* soundName, bool loop )
{
	CSoundManager* sm = __MGR_SOUNDS();

	IAttributes* attr = CGameConfig::GetInstance()->getAttributes( L"sounds", m_SoundsPackName );

	/// Find sound alternates number
	s32 num = 0;
	stringc str;
	stringc name( soundName );
	do 
	{
		if( num == 0 )
			str = name;
		else
			str = name + "_" + stringc( num );		

		num++;
	} while( attr->getAttributeAsString( str.c_str() ).size() > 0 );
	num--;

	if( num < 1 )			
		return false; 

	/// Play sound
	s32 r = rand() % num;
	
	if( r > 0 )
	{
		str = str = name + "_" + stringc( r );		
		str = attr->getAttributeAsString( str.c_str() );
	}
	else
	{
		str = attr->getAttributeAsString( name.c_str() );
	}

	s32 idx = sm->GetSoundIndexFromName( str.c_str() );
	if( idx < 0 )
		return false;

	IAttributes* configAttr = CGameConfig::GetInstance()->getAttributes( L"soundsconfig",  stringw(str.c_str()));

	
	if(configAttr != 0 && configAttr->getAttributeAsInt("Obligatory") == 0)
	{
		position2di pos = getScreenPosition();
		//rect<s32> viewport = m_SceneManager->getVideoDriver()->getViewPort();
		rect<s32> viewport(0, 0, GAME_SCREEN_W, GAME_SCREEN_H);
		if(!viewport.isPointInside(pos))
			return CPlayfield::GetInstance()->PlaySfx( idx, loop, 0, 100 );
	}

	return CPlayfield::GetInstance()->PlaySfx( idx, loop );
}

