int CUnit::getDragPriority ()
{
	if (isPetrified()) return 100;
	if (m_unitKind == UK_Elf) return 80;
	if (m_unitKind == UK_Shaman) return 60;
	if (m_unitKind == UK_Troll) return 50;
	if (m_unitKind == UK_Skeleton) return 40;
	if (m_unitKind == UK_Goblin && m_statSpeed > 3.0f) return 20;
	return 0;
}

void CUnit::hideAura ()
{
	if (m_shamanAura) m_shamanAura->hideImmediately();
}

void CUnit::OptimizedCleanUnit (UnitParameters* params, ISceneNode* node)
{
	list<ISceneNode*>::ConstIterator it = node->getChildren().begin();
	for (; it != node->getChildren().end();)
	{
		ISceneNode * child = (*it);
		it++;
		OptimizedCleanUnit(params, child); 
	}

	if (node->getType() == ESNT_LIGHT || node->getType() == ESNT_COLLADA_CAMERA)
	{
		node->remove();
		return;
	}

	const char* name = node->getName();
	if (m_bip01 == 0 && strcmp(name, "Bip01") == 0)
		m_bip01 = node;
	if (m_chestDummy == 0 && strcmp(name, params->chestDummy.c_str()) == 0)
		m_chestDummy = node;
	if (m_dragDummy == 0 && strcmp(name, params->dragDummy.c_str()) == 0)
		m_dragDummy = node;
	if (m_energyBallDummy == 0 && strcmp(name, params->energyBallDummy.c_str()) == 0)
		m_energyBallDummy = node;
	if (m_headDummy == 0 && strcmp(name, "Bip01_Head") == 0)
		m_headDummy = node;
	if (m_shamanStaffDummy == 0 && strcmp(name, "d_magic") == 0)
		m_shamanStaffDummy = node;
	if (m_unitKind == UK_Bomblin && strcmp(name, "Bip01_Prop1") == 0)
		node->addChild(m_bomb->getRoot());
	for (int i = 0; i < params->textureObjects.size(); ++i)
	{
		if (strcmp(name, params->textureObjects[i].c_str()) == 0)
		{
			ITexture* tex = __IRR_DRIVER()->getTexture(params->textureFiles[i].c_str());
			node->getChildren().getFirstElem()->getMaterial(0).setTexture(0, tex);
		}
	}

	for (int i = 0; i < node->getMaterialCount(); ++i)
	{
		SMaterial& material = node->getMaterial(i);

		material.setFlag(EMF_NORMALIZE_NORMALS, true);
		material.setFlag(EMF_LIGHTING, true);
		material.setEmissiveColor(CGameConfig::EmissiveColorForInteractiveObjects);
		material.setShininess(0.0f);

		material.setMaterialType(EMT_TRANSPARENT_ALPHA_CHANNEL_REF);
		material.setFlag(EMF_BACK_FACE_CULLING, true);
	}
}

void CUnit::OptimizedCleanShadow (UnitParameters* params, ISceneNode* node)
{
	list<ISceneNode*>::ConstIterator it = node->getChildren().begin();
	for (; it != node->getChildren().end();)
	{
		ISceneNode * child = (*it);
		it++;
		OptimizedCleanShadow(params, child); 
	}

	if (node->getType() == ESNT_LIGHT || node->getType() == ESNT_COLLADA_CAMERA)
	{
		node->remove();
		return;
	}

	if (node->getType() == ESNT_COLLADA_MESH)
		m_shadowMesh = (CColladaMeshSceneNode*)node;

	for (int i = 0; i < node->getMaterialCount(); ++i)
	{
		SMaterial& material = node->getMaterial(i);
		material.setFlag(EMF_NORMALIZE_NORMALS, true);
		material.setFlag(EMF_LIGHTING, true);
		material.setEmissiveColor(0x00000000);
		material.setShininess(0.0f);
	}
}
